def hamming_distance(a, b):
    a = list(a)
    b = list(b)
    if len(a) != len(b):
        raise ValueError('a and b must have equal length')
    total = 0
    for x, y in zip(a, b):
        total += bin(x ^ y).count('1')
    return total
